import{_ as d,c as t,e as f,o as s}from"./index-DUl6PKBW.js";const o={name:"ConferencePage"},r={class:"container py-5"};function l(v,a,e,c,i,n){return s(),t("div",r,a[0]||(a[0]=[f('<h1 class="text-center mb-4" data-v-5f539f0d> Ежегодная научно-образовательная конференция<br data-v-5f539f0d><small class="text-muted" data-v-5f539f0d>&quot;Неврологические образовательные университеты&quot;</small></h1><p data-v-5f539f0d> Уже на протяжении более 20 лет проводится ежегодная конференция. В программу включаются различные актуальные вопросы неврологии и смежных специальностей, акцентируя внимание на новые направления и междисциплинарное взаимодействие. </p><div class="alert alert-info mt-4" data-v-5f539f0d><strong data-v-5f539f0d>Годы проведения: </strong><a href="#" class="link-primary text-decoration-none" data-v-5f539f0d>2016</a>, <a href="/educational/2017" class="link-primary text-decoration-none" data-v-5f539f0d>2017</a>, <a href="/educational/2018" class="link-primary text-decoration-none" data-v-5f539f0d>2018</a></div><div class="card my-5" data-v-5f539f0d><div class="card-body" data-v-5f539f0d><h5 class="card-title" data-v-5f539f0d>Формат конференции 2018 года</h5><p class="card-text" data-v-5f539f0d> Впервые конференция прошла в формате междисциплинарного взаимодействия неврологов и нейрохирургов под руководством профессора Владимира Ивановича Шмырева и д.м.н. Ольги Бенуаовны Белоусовой. Рассматривались темы боли и сосудистых нарушений, принципы диагностики, современные методы лечения и реабилитации. </p></div></div><h4 data-v-5f539f0d>Особое внимание:</h4><ul data-v-5f539f0d><li data-v-5f539f0d>Неинвазивные и малоинвазивные методы лечения.</li><li data-v-5f539f0d>Алгология в неврологии.</li><li data-v-5f539f0d>Нейрохирургия и нейрореабилитация.</li><li data-v-5f539f0d>Проблемы сосудистой неврологии.</li></ul><p class="mt-4" data-v-5f539f0d> Докладчик от французской школы — <strong data-v-5f539f0d>Серж Лашер</strong>, эксперт по KISS-синдрому, представил доклад, вызвавший большой интерес. </p><div class="card my-5" data-v-5f539f0d><div class="card-body" data-v-5f539f0d><h5 class="card-title" data-v-5f539f0d>Мастер-класс</h5><p class="card-text" data-v-5f539f0d> &quot;Миофасциальные и биомеханические нарушения в клинической практике&quot; провёл доцент Алексей Сергеевич Васильев. </p></div></div><h4 data-v-5f539f0d>Научные руководители:</h4><ul data-v-5f539f0d><li data-v-5f539f0d><strong data-v-5f539f0d>Владимир Иванович Шмырев</strong> — д.м.н., профессор, заведующий кафедрой неврологии ФГБУ &quot;ЦЛГМА&quot; УД Президента РФ, главный специалист по неврологии ГМУ УД Президента РФ. </li><li data-v-5f539f0d><strong data-v-5f539f0d>Алексей Сергеевич Васильев</strong> — к.м.н., доцент кафедры неврологии ФГБУ &quot;ЦЛГМА&quot; УД Президента РФ. </li></ul><div class="card my-5" data-v-5f539f0d><div class="card-body" data-v-5f539f0d><h5 class="card-title" data-v-5f539f0d>Провайдер конференции</h5><p class="card-text" data-v-5f539f0d><strong data-v-5f539f0d>ООО &quot;Медзнания&quot;</strong><br data-v-5f539f0d> 127083, г.Москва, Большой Каретный пер., 7<br data-v-5f539f0d> Телефон: (495) 699-14-65, 699-81-84<br data-v-5f539f0d> E-mail: <a href="mailto:info@medg.ru" data-v-5f539f0d>info@medg.ru</a></p></div></div>',11)]))}const p=d(o,[["render",l],["__scopeId","data-v-5f539f0d"]]);export{p as default};
